# Compatibility tests against CRAN careless 1.2.2
# Reference archive: https://cloud.r-project.org/src/contrib/careless_1.2.2.tar.gz
# Archive SHA-256: 6AD3D4C8B1B2910A7C2E98C5A8BF37E65071164D13BA66896490D9FFCB678ED9
# Fixtures generated by: tests/testthat/fixtures/generate-careless-1.2.2-fixtures.R

data("careless_dataset", package = "Satisficing")
data("careless_dataset2", package = "Satisficing")

test_that("careless datasets fully match upstream careless 1.2.2 datasets", {
  # Load reference datasets directly from upstream RDA fixtures
  fixture_env <- new.env(parent = emptyenv())
  load(testthat::test_path("fixtures", "careless_dataset.rda"), envir = fixture_env)
  load(testthat::test_path("fixtures", "careless_dataset2.rda"), envir = fixture_env)

  # Full object comparison: class, dim, dimnames, attributes, and all cell values
  expect_identical(careless_dataset, fixture_env$careless_dataset)
  expect_identical(careless_dataset2, fixture_env$careless_dataset2)
})

test_that("longstring matches upstream careless 1.2.2 behavior", {
  # Test with upstream test matrix (reproducing inst/testdata/lonstring-test-data.csv)
  row_builder <- function(reps) {
    c(rep(1, reps), rep(c(0, 1), length.out = 100 - reps))
  }
  m <- matrix(0, nrow = 10, ncol = 100)
  for (i in 1:9) {
    m[i, ] <- row_builder(i * 10)
  }
  m[10, ] <- rep(c(rep(1, 10), rep(0, 10)), length.out = 100)

  expect_identical(longstring(m), as.numeric(c(1:9 * 10, 10)))

  # avg = TRUE
  df_avg <- longstring(m[1:3, ], avg = TRUE)
  expect_s3_class(df_avg, "data.frame")
  expect_identical(colnames(df_avg), c("longstr", "avgstr"))
  expect_identical(df_avg$longstr, as.numeric(c(10, 20, 30)))

  # Simple fixture from oracle careless 1.2.2
  simple_m <- matrix(c(1, 1, 1, 2, 3, 3, 3, 3, 1, 2, 3, 4), nrow = 3, byrow = TRUE)
  expect_identical(longstring(simple_m), c(3, 4, 1))
  expect_identical(longstring(simple_m, avg = TRUE)$avgstr, c(2, 4, 1))
})

test_that("irv matches upstream careless 1.2.2 behavior", {
  irv_mat <- matrix(c(1, 2, 3, 4, 5, 6, 2, 2, 2, 2, 2, 2), nrow = 2, byrow = TRUE)

  # Full calculation
  res_total <- irv(irv_mat)
  expect_equal(res_total, c(1.87082869338697, 0), tolerance = 1e-7)

  # split = TRUE
  res_split <- irv(irv_mat, split = TRUE, num.split = 2)
  expect_s3_class(res_split, "data.frame")
  expect_identical(colnames(res_split), c("irvTotal", "irv1", "irv2"))
  expect_equal(res_split$irvTotal, c(1.87082869338697, 0), tolerance = 1e-7)
  expect_equal(res_split$irv1, c(1, 0), tolerance = 1e-7)
  expect_equal(res_split$irv2, c(1, 0), tolerance = 1e-7)

  # na.rm handling
  mat_na <- matrix(c(1, 2, NA, 4), nrow = 1)
  expect_false(is.na(irv(mat_na, na.rm = TRUE)))
  expect_true(is.na(irv(mat_na, na.rm = FALSE)))
})

test_that("evenodd matches upstream careless 1.2.2 behavior and warnings", {
  sample_data <- careless_dataset[1:10, 1:20]
  expected_eo <- c(
    -0.322780955592818, -0.618033988749895, -0.373210993726742,
    -0.427877538267963, -0.935213074469699, 0.140858123074528,
    -0.912375826453062, 1, -0.918058124456122, 1
  )

  # Warns about computation change in v1.2.0
  expect_warning(res <- evenodd(sample_data, factors = rep(5, 4)), "Computation of even-odd has changed")
  expect_equal(res, expected_eo, tolerance = 1e-7)

  # diag = TRUE
  expect_warning(res_diag <- evenodd(sample_data, factors = rep(5, 4), diag = TRUE), "Computation of even-odd has changed")
  expect_s3_class(res_diag, "data.frame")
  expect_equal(res_diag$eo_cor, expected_eo, tolerance = 1e-7)

  # Error on single factor
  expect_error(suppressWarnings(evenodd(sample_data, factors = 20)), "single factor")

  # Error when factors exceed ncol
  expect_error(suppressWarnings(evenodd(sample_data, factors = c(10, 15))), "exceeds the number of columns")

  # Warning when factors do not match ncol
  warns <- capture_warnings(evenodd(sample_data, factors = c(5, 5)))
  expect_true(any(grepl("does not match the number of columns", warns)))
})

test_that("psychsyn_critval matches upstream careless 1.2.2 behavior", {
  sub_data <- careless_dataset[1:20, 1:5]

  # anto = FALSE (descending)
  cv_pos <- psychsyn_critval(sub_data, anto = FALSE)
  expect_s3_class(cv_pos, "data.frame")
  expect_identical(names(cv_pos), c("var1", "var2", "cor"))
  valid_pos <- stats::na.omit(cv_pos$cor)
  expect_true(all(diff(valid_pos) <= 0)) # descending
  expect_equal(cv_pos$cor[1:3], c(0.643433679343034, 0.511751200417798, 0.434633560328094), tolerance = 1e-7)

  # anto = TRUE (ascending)
  cv_neg <- psychsyn_critval(sub_data, anto = TRUE)
  valid_neg <- stats::na.omit(cv_neg$cor)
  expect_true(all(diff(valid_neg) >= 0)) # ascending
  expect_equal(cv_neg$cor[1:3], c(-0.136319635318199, -0.00240506250114127, 0.00686301226202113), tolerance = 1e-7)
})

test_that("psychsyn matches upstream careless 1.2.2 behavior (deterministic, resampled, and RNG preservation)", {
  # Save caller RNG state
  old_rng <- RNGkind()
  old_seed <- if (exists(".Random.seed", envir = .GlobalEnv)) get(".Random.seed", envir = .GlobalEnv) else NULL
  on.exit({
    if (!is.null(old_seed)) assign(".Random.seed", old_seed, envir = .GlobalEnv) else rm(".Random.seed", envir = .GlobalEnv)
    RNGkind(old_rng[1], old_rng[2], old_rng[3])
  }, add = TRUE)

  sub_data <- careless_dataset[1:15, ]
  expected_cor <- c(
    0.124011545949806, 0.285226821919184, 0.206345073528437, 0.242624312712031,
    0.317505397241044, 0.330783209156595, 0.124445601345462, 0.264029666084661,
    0.393115022435895, 0.314544489768272, 0.448213432112181, 0.111600915475659,
    0.137699050926623, 0.116024174941231, 0.0193911196769091
  )

  # Deterministic case (resample_na = FALSE)
  res_det <- psychsyn(sub_data, critval = 0.50, resample_na = FALSE)
  expect_equal(res_det, expected_cor, tolerance = 1e-7)

  # diag = TRUE
  res_diag <- psychsyn(sub_data, critval = 0.50, diag = TRUE, resample_na = FALSE)
  expect_s3_class(res_diag, "data.frame")
  expect_identical(colnames(res_diag), c("numPairs", "cor"))
  expect_identical(res_diag$numPairs, rep(357, 15))
  expect_equal(res_diag$cor, expected_cor, tolerance = 1e-7)

  # Error when no synonyms meet threshold
  expect_error(psychsyn(sub_data, critval = 0.99), "No Psychometric Synonyms found")

  # Resample branch verification:
  # In row 1 of mat_resample, initial correlation of item pairs has zero variance and yields NA.
  # With resample_na = FALSE, it returns NA.
  # With resample_na = TRUE under fixed seed, it enters the resampling loop and returns a valid correlation.
  set.seed(1)
  n <- 30
  x1 <- rnorm(n); x2 <- x1 + rnorm(n, sd = 0.1)
  x3 <- rnorm(n); x4 <- x3 + rnorm(n, sd = 0.1)
  x5 <- rnorm(n); x6 <- x5 + rnorm(n, sd = 0.1)
  mat_resample <- data.frame(X1 = x1, X2 = x2, X3 = x3, X4 = x4, X5 = x5, X6 = x6)
  mat_resample[1, ] <- c(1, 2, 1, 3, 1, 4)

  # resample_na = FALSE returns NA for row 1
  res_no_resample <- psychsyn(mat_resample, critval = 0.8, resample_na = FALSE)
  expect_true(is.na(res_no_resample[1]))

  # resample_na = TRUE with seed triggers resample loop and resolves NA to oracle value
  RNGkind("Mersenne-Twister", "Inversion", "Rejection")
  set.seed(123)
  seed_before <- get(".Random.seed", envir = .GlobalEnv)
  res_with_resample <- psychsyn(mat_resample, critval = 0.8, resample_na = TRUE)
  seed_after <- get(".Random.seed", envir = .GlobalEnv)

  # Confirm the resampling loop altered the RNG state
  expect_false(identical(seed_before, seed_after))
  # Confirm the result matches careless 1.2.2 oracle
  expect_equal(res_with_resample[1], -0.755928946018455, tolerance = 1e-7)
})

test_that("caller RNG state is preserved after psychsyn test", {
  # Verify that the test above properly restored caller RNG state
  old_rng <- RNGkind()
  set.seed(999)
  val1 <- runif(1)

  # Run psychsyn with RNG changes inside
  sub_data <- careless_dataset[1:10, 1:5]
  psychsyn(sub_data, critval = 0.50, resample_na = FALSE)

  set.seed(999)
  val2 <- runif(1)
  expect_identical(val1, val2)
})

test_that("psychant matches upstream careless 1.2.2 behavior", {
  sub_data2 <- careless_dataset2[1:15, ]
  expected_ant <- c(
    -0.724378919497016, -0.470150023455036, -0.410203881610932,
    -0.523727331758738, -0.470680297664074, -0.59241381780098,
    -0.427316380915575, -0.558195847280457, -0.36249112020497,
    -0.371227326821161, -0.611758849187781, -0.474724153442769,
    -0.469202754377203, -0.284430801537588, -0.616887738291964
  )

  res_ant <- psychant(sub_data2, critval = -0.50)
  expect_equal(res_ant, expected_ant, tolerance = 1e-7)

  res_ant_diag <- psychant(sub_data2, critval = -0.50, diag = TRUE)
  expect_s3_class(res_ant_diag, "data.frame")
  expect_identical(colnames(res_ant_diag), c("numPairs", "cor"))
  expect_identical(res_ant_diag$numPairs, rep(160, 15))
  expect_equal(res_ant_diag$cor, expected_ant, tolerance = 1e-7)

  # Error when no antonyms found
  expect_error(psychant(sub_data2, critval = -0.99), "No Psychometric Antonyms found")
})

test_that("mahad matches upstream careless 1.2.2 behavior (plot = FALSE)", {
  sub_data <- careless_dataset[1:10, 1:5]
  expected_dsq <- c(
    3.90950769057781, 3.39962800372933, 4.28207437114359, 3.22961540083301,
    5.47116115309474, 5.08071616309741, 4.17284380373215, 3.8235526580867,
    5.03410184452055, 6.59679891118472
  )

  # Without flags
  res_dsq <- mahad(sub_data, plot = FALSE)
  expect_equal(res_dsq, expected_dsq, tolerance = 1e-7)

  # With flags
  res_flag <- mahad(sub_data, plot = FALSE, flag = TRUE, confidence = 0.95)
  expect_s3_class(res_flag, "data.frame")
  expect_identical(colnames(res_flag), c("d_sq", "flagged"))
  expect_equal(res_flag$d_sq, expected_dsq, tolerance = 1e-7)
  expect_false(any(res_flag$flagged))

  # Missing values handling
  sub_na <- sub_data
  sub_na[1, 1] <- NA
  expect_error(mahad(sub_na, plot = FALSE, na.rm = FALSE), "Some values are NA")
  expect_false(is.na(mahad(sub_na, plot = FALSE, na.rm = TRUE)[2]))

  # Complete NA row warning
  sub_all_na <- sub_data
  sub_all_na[1, ] <- NA
  expect_warning(mahad(sub_all_na, plot = FALSE), "Some cases contain only NA values")
})
